SIZE_LABELS = {"Стандартный": "", "S": "s", "M": "m", "L": "l"}


def copy_prices_of_existing_orders(apps, schema_editor):
    """Orders placed before this change keep the prices their order lines recorded."""
    ShopOrder = apps.get_model("market", "ShopOrder")
    ShopOrderItem = apps.get_model("market", "ShopOrderItem")
    Listing = apps.get_model("market", "Listing")
    Line = apps.get_model("order", "Line")
    cent = Decimal("0.01")
    for part in ShopOrder.objects.select_related("shop").iterator():
        lines = Line.objects.filter(
            order_id=part.order_id, partner_id=part.shop.partner_id
        )
        for line in lines:
            size = ""
            for attribute in line.attributes.all():
                if attribute.type == "bouquet-size":
                    size = SIZE_LABELS.get(attribute.value, "")
            price = Decimal(line.unit_price_incl_tax).quantize(cent)
            commission = (price * part.commission_percent / 100).quantize(
                cent, rounding=ROUND_HALF_UP
            )
            ShopOrderItem.objects.create(
                part=part,
                listing=Listing.objects.filter(product_id=line.product_id).first(),
                title=line.title[:255],
                size=size,
                quantity=line.quantity,
                unit_price=price,
                unit_commission=commission,
                unit_payout=price - commission,
                commission_percent=part.commission_percent,
            )


def post_existing_payments(apps, schema_editor):
    """Parts already marked paid (all of them online) get their balance entries."""
    ShopOrder = apps.get_model("market", "ShopOrder")
    BalanceEntry = apps.get_model("market", "BalanceEntry")
    for part in ShopOrder.objects.filter(payment_status__in=["paid", "refunded"]):
        if part.partner_total:
            BalanceEntry.objects.create(
                shop_id=part.shop_id,
                part=part,
                kind="platform_collected",
                amount=part.partner_total,
            )
        if part.payment_status == "refunded" and part.partner_total:
            BalanceEntry.objects.create(
                shop_id=part.shop_id,
                part=part,
                kind="refund",
                amount=-part.partner_total,
            )


